FUNCTION_BLOCK FB
VAR_INPUT
    runRequest  : BOOL;
    flameOK     : BOOL;
    o2Valid     : BOOL;
    o2PV        : REAL;
    baseAir     : REAL;
    resetBtn    : BOOL;
END_VAR
VAR_OUTPUT
    fuelPermit  : BOOL;
    trimEnable  : BOOL;
    airTrim     : REAL;
    airCommand  : BOOL;
    tripLatched : BOOL;
    o2Fault     : BOOL;
END_VAR
VAR
    prevResetBtn : BOOL := FALSE;
END_VAR

// Edge detection for reset button
VAR_TEMP
    resetRising : BOOL;
END_VAR

resetRising := resetBtn AND NOT prevResetBtn;

// Trip latch: set on flame loss during run, clear only on valid reset edge
IF runRequest AND NOT flameOK THEN
    tripLatched := TRUE;
ELSIF resetRising AND NOT runRequest AND NOT flameOK THEN
    tripLatched := FALSE;
END_IF

// Update reset button history
prevResetBtn := resetBtn;

// Fuel permit: requires run, flame, and no trip
fuelPermit := runRequest AND flameOK AND NOT tripLatched;

// O2 fault detection
o2Fault := NOT o2Valid OR o2PV < 0.0 OR o2PV > 21.0;

// Trim enable: fuel permit and no O2 fault
trimEnable := fuelPermit AND NOT o2Fault;

// Air trim calculation
IF trimEnable THEN
    airTrim := 2.0 * (2.0 - o2PV);
    IF airTrim > 10.0 THEN
        airTrim := 10.0;
    ELSIF airTrim < -10.0 THEN
        airTrim := -10.0;
    END_IF
ELSE
    airTrim := 0.0;
END_IF

// Air command
IF fuelPermit THEN
    airCommand := baseAir + airTrim;
    IF airCommand > 100.0 THEN
        airCommand := 100.0;
    ELSIF airCommand < 0.0 THEN
        airCommand := 0.0;
    END_IF
ELSE
    airCommand := 0.0;
END_IF

END_FUNCTION_BLOCK
